const normalizeState = (v) => ({...baseState(),...v,profile:{...blankProfile(),...(v.profile&&typeof v.profile==='object'?v.profile:{})},weights:Array.isArray(v.weights)?v.weights:[],meals:Array.isArray(v.meals)?v.meals:[],waters:Array.isArray(v.waters)?v.waters:[],workouts:Array.isArray(v.workouts)?v.workouts:[],sets:Array.isArray(v.sets)?v.sets:[],measurements:Array.isArray(v.measurements)?v.measurements:[],recovery:Array.isArray(v.recovery)?v.recovery:[],favorites:Array.isArray(v.favorites)?v.favorites:[],customFoods:Array.isArray(v.customFoods)?v.customFoods:[],routineEdits:v.routineEdits&&typeof v.routineEdits==='object'?v.routineEdits:{},customRoutines:Array.isArray(v.customRoutines)?v.customRoutines:[]});
