  const saveSet = (e) => { e.preventDefault(); const r=Number(reps),kg=Number(load); if(!currentWorkout) return notify('Start a workout first.'); if(!exercise.trim()||r<1||r>100||kg<0||kg>1000) return notify('Check exercise, reps and load.'); const set={id:id(),sessionId:currentWorkout.id,exercise,reps:r,kg,createdAt:Date.now()}; setData(d=>({...d,sets:[set,...d.sets],workouts:d.workouts.map(w=>w.id===currentWorkout.id?{...w,sets:(w.sets||0)+1,completed:[...new Set([...(w.completed||[]),exercise])]}:w)})); notify('Set saved'); };
